interface DocumentState {
  void publish(Document doc);
  void approve(Document doc, User user);
  void reject(Document doc);
}

final class DraftState implements DocumentState {
  public void publish(Document doc) {
    doc.setState(new ModerationState());
  }
  public void approve(Document doc, User user) {
    throw new IllegalStateException("cannot approve a draft");
  }
  public void reject(Document doc) {
    throw new IllegalStateException("draft is not under review");
  }
}

final class ModerationState implements DocumentState {
  public void publish(Document doc) { /* no-op: already submitted */ }
  public void approve(Document doc, User user) {
    if (!user.isAdmin()) throw new SecurityException("admin only");
    doc.setState(new PublishedState());
  }
  public void reject(Document doc) {
    doc.setState(new DraftState());
  }
}

final class PublishedState implements DocumentState {
  public void publish(Document doc) { /* no-op */ }
  public void approve(Document doc, User user) { /* no-op */ }
  public void reject(Document doc) {
    throw new IllegalStateException("published doc cannot return to draft");
  }
}

final class Document {
  private DocumentState state = new DraftState();
  void setState(DocumentState next) { this.state = next; }
  public void publish() { state.publish(this); }
  public void approve(User u) { state.approve(this, u); }
  public void reject() { state.reject(this); }
}
